create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,role text not null default 'staff' check(role in ('owner','admin','manager','accountant','staff')),active boolean not null default true,created_at timestamptz not null default now());
create or replace function public.is_active_user() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and active=true); $$;
create or replace function public.has_any_role(allowed text[]) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and active=true and role=any(allowed)); $$;
create table if not exists public.clients(id uuid primary key default gen_random_uuid(),name text not null,phone text,email text,passport_no text,notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.vendors(id uuid primary key default gen_random_uuid(),name text not null,phone text,email text,notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.tickets(id uuid primary key default gen_random_uuid(),invoice_no text unique,passenger_name text not null,client_id uuid references public.clients(id) on delete set null,pnr text,airline text,route text,travel_date date,cost_amount numeric(12,2) not null default 0 check(cost_amount>=0),sale_amount numeric(12,2) not null default 0 check(sale_amount>=0),status text not null default 'booked' check(status in ('booked','issued','cancelled','refunded')),notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.transactions(id uuid primary key default gen_random_uuid(),transaction_type text not null check(transaction_type in ('income','expense','receipt','payment')),category text not null,amount numeric(12,2) not null check(amount>0),method text not null default 'cash' check(method in ('cash','bank','mobile_banking','card','other')),reference text,description text,transaction_date date not null default current_date,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.services(id uuid primary key default gen_random_uuid(),service_type text not null check(service_type in ('visa','hajj','umrah','hotel','transport','other')),client_id uuid references public.clients(id) on delete set null,applicant_name text not null,passport_no text,country text,status text not null default 'pending',cost_amount numeric(12,2) not null default 0 check(cost_amount>=0),sale_amount numeric(12,2) not null default 0 check(sale_amount>=0),notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.audit_logs(id bigint generated always as identity primary key,actor_id uuid references auth.users(id),action text not null,table_name text not null,record_id text,created_at timestamptz not null default now());
alter table public.profiles enable row level security;alter table public.clients enable row level security;alter table public.vendors enable row level security;alter table public.tickets enable row level security;alter table public.transactions enable row level security;alter table public.services enable row level security;alter table public.audit_logs enable row level security;
create policy "profiles read self/admin" on public.profiles for select to authenticated using(id=auth.uid() or public.has_any_role(array['owner','admin']));
create policy "profiles admin update" on public.profiles for update to authenticated using(public.has_any_role(array['owner','admin'])) with check(public.has_any_role(array['owner','admin']));
create policy "clients read active" on public.clients for select to authenticated using(public.is_active_user());
create policy "clients insert active" on public.clients for insert to authenticated with check(public.is_active_user() and created_by=auth.uid());
create policy "clients update manager" on public.clients for update to authenticated using(public.has_any_role(array['owner','admin','manager','staff'])) with check(public.is_active_user());
create policy "clients delete admin" on public.clients for delete to authenticated using(public.has_any_role(array['owner','admin']));
create policy "vendors read active" on public.vendors for select to authenticated using(public.is_active_user());
create policy "vendors insert active" on public.vendors for insert to authenticated with check(public.is_active_user() and created_by=auth.uid());
create policy "vendors update finance" on public.vendors for update to authenticated using(public.has_any_role(array['owner','admin','manager','accountant'])) with check(public.is_active_user());
create policy "vendors delete admin" on public.vendors for delete to authenticated using(public.has_any_role(array['owner','admin']));
create policy "tickets read active" on public.tickets for select to authenticated using(public.is_active_user());
create policy "tickets insert active" on public.tickets for insert to authenticated with check(public.is_active_user() and created_by=auth.uid());
create policy "tickets update staff" on public.tickets for update to authenticated using(public.has_any_role(array['owner','admin','manager','staff'])) with check(public.is_active_user());
create policy "tickets delete admin" on public.tickets for delete to authenticated using(public.has_any_role(array['owner','admin']));
create policy "transactions read finance" on public.transactions for select to authenticated using(public.has_any_role(array['owner','admin','manager','accountant']));
create policy "transactions insert finance" on public.transactions for insert to authenticated with check(public.has_any_role(array['owner','admin','manager','accountant']) and created_by=auth.uid());
create policy "transactions update finance" on public.transactions for update to authenticated using(public.has_any_role(array['owner','admin','accountant'])) with check(public.has_any_role(array['owner','admin','accountant']));
create policy "transactions delete admin" on public.transactions for delete to authenticated using(public.has_any_role(array['owner','admin']));
create policy "services read active" on public.services for select to authenticated using(public.is_active_user());
create policy "services insert active" on public.services for insert to authenticated with check(public.is_active_user() and created_by=auth.uid());
create policy "services update staff" on public.services for update to authenticated using(public.has_any_role(array['owner','admin','manager','staff'])) with check(public.is_active_user());
create policy "services delete admin" on public.services for delete to authenticated using(public.has_any_role(array['owner','admin']));
create policy "audit read admin" on public.audit_logs for select to authenticated using(public.has_any_role(array['owner','admin']));
